steps.script:
#!/bin/bash
set -euo pipefail
enabled=$(kubectl get configmap cluster-config -n konflux-info -o jsonpath='{.data.allow-cache-proxy}')
[[ "$enabled" == true ]] || { echo 'cluster-config does not enable the cache proxy' >&2; exit 1; }
proxy=$(kubectl get configmap cluster-config -n konflux-info -o jsonpath='{.data.http-proxy}')
proxy=${proxy//$'\r'/}
proxy=${proxy//$'\n'/}
[[ -n "$proxy" ]] || { echo 'cluster-config http-proxy is empty' >&2; exit 1; }
case "$proxy" in
  http://*) ;;
  *://*) echo "cluster-config uses an unsupported proxy scheme: $proxy" >&2; exit 1 ;;
  *) proxy="http://$proxy" ;;
esac
expected=http://squid.container-image-proxy.svc.cluster.local:3128
[[ "$proxy" == "$expected" ]] || { echo "cluster-config selects $proxy, expected $expected" >&2; exit 1; }
printf '%s' "$proxy" > /workspace/proxy/http-proxy
echo "Validated cluster-config endpoint: $proxy"
